  "member.how": "{payMethods}, {gateway} வழியாக, மையத்தின் சொந்தக் கணக்கிற்கு.",
  "member.autoRenew": "ஒவ்வொரு முறையும் கார்டு மூலம் தானாகப் புதுப்பி",
  "member.renewing": "இந்த உறுப்பினர் சந்தா {until} அன்று முடியும்போது தானாகப் புதுப்பிக்கப்படும். எப்போது வேண்டுமானாலும் நிறுத்தலாம்: உங்களிடம் உள்ளது அதன் முடிவு வரை செல்லுபடியாகும்.",
