  "privacy.metaTitle": "தனியுரிமை அறிவிப்பு · {site}",
  "privacy.metaDescription": "{site} உங்களைப் பற்றி என்ன வைத்திருக்கிறது, ஏன், எவ்வளவு காலம், அதை எப்படித் திரும்பப் பெறுவது அல்லது நீக்குவது.",
  "privacy.title": "தனியுரிமை அறிவிப்பு",
  "privacy.intro": "இந்தத் தளத்தில் பட்டியலிடப்பட்டுள்ள மையங்களுக்காக {site} கோர்ட்டுகள், ஜிம் இடங்கள், வகுப்புகளை முன்பதிவு செய்கிறது. உங்களைப் பற்றி நாங்கள் என்ன வைத்திருக்கிறோம், ஏன், எவ்வளவு காலம், அதைப் பற்றி நீங்கள் என்ன செய்யலாம் என்பதை இது கூறுகிறது. இது சிரமப்பட்டுப் படிக்க அல்ல, எளிதாகப் புரிந்துகொள்ள எழுதப்பட்டது.",
