  "acct.cancelledLower": "ரத்து செய்யப்பட்டது",
  "acct.seriesTitle": "வாராந்திரத் தொடரின் ஒரு பகுதி",
  "acct.paid": "✓ செலுத்தப்பட்டது",
  "acct.payAtCounter": "(கவுண்டரில் செலுத்துங்கள்)",
  "acct.share": "பகிர்",
