  "err.NO_SPORT_AT_VENUE": "அந்த மையத்தில் {sport} கோர்ட்டுகள் இல்லை.",
  "err.SPORT_NOT_HERE": "அந்த இடம் {sport} முன்பதிவுக்கு இல்லை.",
  "err.SIGN_OFF_NEEDED": "இங்கு {sport} செய்ய முதலில் மைய ஊழியர்களின் ஒப்புதல் (பாதுகாப்புச் சோதனை போன்றது) தேவை. ஒப்புதல் பெற்ற, தொலைபேசி எண் சரிபார்க்கப்பட்ட கணக்கில் உள்நுழையுங்கள், அல்லது கவுண்டரில் கேளுங்கள்: அவர்கள் உங்களுக்கு முன்பதிவு செய்வார்கள்.",
  "err.CERTIFICATION_NEEDED": "இங்கு {sport} செய்ய மையம் உங்களுக்காகப் பதிவு செய்த சான்றிதழ் (உரிமம் போன்றது) தேவை. அது பதிவு செய்யப்பட்ட கணக்கில் உள்நுழையுங்கள், அல்லது கவுண்டரில் கேளுங்கள்.",
  "err.SIGN_OFF_EACH": "இங்கு {sport} செய்யும் ஒவ்வொருவருக்கும் தனி ஒப்புதல் தேவை; உங்களுக்கு ஒரு இடத்தை மட்டும் முன்பதிவு செய்யுங்கள், அல்லது குழுவை கவுண்டரில் முன்பதிவு செய்யுங்கள்.",
  "err.NO_COURT_FREE": "அந்த முழு நேரத்திற்கும் எந்தக் கோர்ட்டும் காலியாக இல்லை. வேறு நேரத்தைத் தேர்ந்தெடுங்கள்.",
  "err.WEEKS_RANGE": "வாரங்கள் 1 முதல் {max} வரை இருக்க வேண்டும்.",
  "err.GROUP_COURTS": "2 முதல் {max} கோர்ட்டுகளை ஒன்றாக முன்பதிவு செய்யுங்கள்.",
  "err.GROUP_ONE_VENUE": "ஒன்றாக முன்பதிவு செய்யப்படும் கோர்ட்டுகள் ஒரே மையத்தில் இருக்க வேண்டும்.",
  "err.GROUP_ONE_COURT_ONLY": "பல கோர்ட்டுகளின் முன்பதிவு ஒரே தேதிக்கானது, கூடுதல்களோ பயிற்சியாளரோ இல்லாமல்: அவற்றை ஒரே கோர்ட்டில் முன்பதிவு செய்யுங்கள்.",
  "err.DATE_OUT_OF_WINDOW_FIRST": "முதல் தேதி முன்பதிவுக் காலத்திற்கு வெளியே உள்ளது.",
  "err.DATE_OUT_OF_WINDOW": "தேதி முன்பதிவுக் காலத்திற்கு வெளியே உள்ளது.",
  "err.NO_HOURS": "குறைந்தது ஒரு மணிநேரத்தைத் தேர்ந்தெடுங்கள்.",
