  "err.HOURS_OUTSIDE_OPENING": "தேர்ந்தெடுத்த மணிநேரங்கள் இயக்க நேரத்திற்கு வெளியே உள்ளன.",
  "err.CLOCK_CHANGE": "அந்த நேரத்தில் கடிகாரம் மாறுகிறது, எனவே முன்பதிவு செய்ய முடியாது: அதற்கு முன் அல்லது பின் ஒரு நேரத்தைத் தேர்ந்தெடுங்கள்.",
  "err.PHONE_BLOCKED": "இந்த மையம் இந்த எண்ணிலிருந்து ஆன்லைன் முன்பதிவுகளை ஏற்பதில்லை. மையத்தை அழையுங்கள்.",
