  "err.GENDER_NEEDED": "இது பெண்களுக்கு மட்டும் அல்லது ஆண்களுக்கு மட்டும். முதலில் நீங்கள் எந்த ஆட்டங்களில் விளையாடுகிறீர்கள் என்று சொல்லுங்கள்.",
  "err.WHO_WOMEN": "இது பெண்களுக்கு மட்டும்.",
