  "review.rules": "உங்கள் முதல் பெயர், முதலெழுத்து, நட்சத்திரங்கள், நீங்கள் விளையாடிய மாதம் ஆகியவற்றுடன் மையத்தின் பக்கத்தில் காட்டப்படும். உங்கள் வருகையைப் பற்றி மட்டும் எழுதுங்கள்: தொலைபேசி எண்கள், இணைப்புகள், தவறான வார்த்தைகள் வேண்டாம். மையம் பொதுவில் பதிலளிக்கலாம், இந்த விதிகளை மீறும் விமர்சனங்கள் நீக்கப்படலாம்.",
