  "mkt.optIn": "{venue} இன் செய்திகளையும் சலுகைகளையும் எனக்கு மின்னஞ்சல் செய்யுங்கள். எப்போது வேண்டுமானாலும் நான் விலகிக்கொள்ளலாம்.",
  "mkt.unsubTitle": "சந்தாவிலிருந்து விலகு",
