  "coachpage.subscribe": "உங்கள் தொலைபேசியின் நாள்காட்டியில் சேருங்கள்",
  "coachpage.private": "இந்தப் பக்கம் உங்களுக்கு மட்டுமே: இது உங்கள் மாணவர்களின் பெயர்களையும் எண்களையும் காட்டுகிறது. இணைப்பைப் பகிராதீர்கள். அது வெளியே கசிந்தால், மையத்திடம் புதிய ஒன்றைக் கேளுங்கள்.",
  "coachpage.unpaid": "இன்னும் செலுத்தப்படவில்லை",
  "coachpage.hoursTitle": "உங்கள் நேரங்கள்",
  "coachpage.hoursBody": "ஒவ்வொரு வாரமும் நீங்கள் பயிற்சி அளிக்கும் நேரம். அந்த நேரங்களில் மட்டுமே மாணவர்கள் உங்களை முன்பதிவு செய்ய முடியும்; ஏற்கனவே முன்பதிவு செய்யப்பட்ட பயிற்சிகள் அப்படியே இருக்கும்.",
  "coachpage.addHours": "நேரம் சேர்",
  "coachpage.save": "சேமி",
  "coachpage.saved": "சேமிக்கப்பட்டது.",
  "coachpage.remove": "நீக்கு",
  "coachpage.from": "முதல்",
  "coachpage.until": "வரை",
  "coachpage.offTitle": "விடுப்பு",
  "coachpage.offBody": "நீங்கள் இல்லாத நாட்கள்: அப்போது யாரும் உங்களை முன்பதிவு செய்ய முடியாது.",
  "coachpage.offFrom": "முதல்",
