  "coachpage.offReason": "குறிப்பு (விருப்பம்)",
  "coachpage.offAdd": "விடுப்பு சேர்",
  "coachpage.offClash_one": "அந்த நேரத்தில் உங்களுக்கு {n} பயிற்சி முன்பதிவு உள்ளது. அதை மாற்ற மையத்திடம் தெரிவியுங்கள்.",
  "coachpage.offClash_other": "அந்த நேரத்தில் உங்களுக்கு {n} பயிற்சிகள் முன்பதிவு உள்ளன. அவற்றை மாற்ற மையத்திடம் தெரிவியுங்கள்.",
  "coach.weeksBooked": "வாராந்திர {n} பயிற்சி வகுப்புகள் முன்பதிவு செய்யப்பட்டன.",
  "coach.weekSkipped": "{date} அன்று முன்பதிவு செய்யப்படவில்லை: {reason}.",
  "split.title": "செலவைப் பகிருங்கள்",
  "split.ways": "நபர்கள், நீங்களும் சேர்த்து",
