  "split.each": "ஒவ்வொரு நண்பரும் ஆன்லைனில் {share} செலுத்துவார்; அவர்கள் செலுத்திய பிறகு மீதியை ({rest}) நீங்கள் செலுத்துவீர்கள், அல்லது ஒன்றும் இல்லை.",
  "split.terms": "முன்பதிவு உங்களுடையதாகவே இருக்கும்: முழுமையாகச் செலுத்தப்படும் வரை மீதமுள்ளதை நீங்கள் செலுத்த வேண்டும், மையத்தின் ரத்து விதிகள் உங்களுக்குப் பொருந்தும். ரத்து செய்யப்பட்டால், நண்பர்களின் பங்குகளை மையம் திருப்பித் தர வேண்டும்.",
  "split.link": "இந்த இணைப்பை உங்கள் நண்பர்களுக்கு அனுப்புங்கள்:",
