  "refund.processing": "{amount} பணத்தைத் திருப்பித் தருவதைக் கட்டண வழங்குநர் செயல்படுத்துகிறார்.",
  "refund.failed": "கட்டண வழங்குநரால் {amount} பணத்தைத் திருப்பித் தர முடியவில்லை. மையத்திற்குத் தெரிவிக்கப்பட்டுள்ளது, அது மீண்டும் திருப்பித் தரும்; தகவல் வராவிட்டால் மையத்தைத் தொடர்புகொள்ளுங்கள்.",
  "err.VOUCHER_NOT_FOUND": "அந்தக் குறியீட்டில் பரிசுச் சீட்டு இல்லை. சரிபார்த்து மீண்டும் முயலுங்கள்.",
  "err.VOUCHER_USED": "அந்தப் பரிசுச் சீட்டு ஏற்கெனவே பயன்படுத்தப்பட்டுவிட்டது.",
  "err.VOUCHER_VOID": "அந்தப் பரிசுச் சீட்டு மையத்தால் ரத்து செய்யப்பட்டது.",
  "err.VOUCHER_EXPIRED": "அந்தப் பரிசுச் சீட்டு {date} அன்று காலாவதியானது.",
