  "apr.documentAsk": "மையம் கேட்பது: {what}",
  "apr.documentNote": "ஒரு புகைப்படம் அல்லது ஸ்கேன் (JPEG, PNG அல்லது WebP), அதிகபட்சம் 3. மைய ஊழியர்களும் அது அனுமதிக்கும் பயிற்சியாளர்களும் மட்டுமே பார்ப்பார்கள்; முடிவுக்குப் பிறகு அது நீக்கப்படும். அடையாள அட்டையையோ கடவுச்சீட்டையோ ஒருபோதும் அனுப்ப வேண்டாம்.",
  "apr.videoLink": "விளக்க வீடியோவைப் பாருங்கள்",
  "apr.videoWatched": "விளக்க வீடியோவை முழுமையாகப் பார்த்துவிட்டேன்.",
  "apr.waiverAgree": "மேலே உள்ள மையத்தின் பொறுப்புத் துறப்பை ஒப்புக்கொள்கிறேன்.",
