  "fit.sec.know": "தெரிந்துகொள்ள வேண்டியவை",
  "fit.sec.knowLead": "சில செயல்பாடுகள் முழுமையாகவும் சில பகுதியளவிலும் ஆதரிக்கப்படுகின்றன. நீங்கள் தேர்ந்தெடுத்த ஒவ்வொன்றையும் பற்றி செயல்பாட்டுப் பட்டியல் சொல்வது இதுதான்.",
