  "fit.sec.combined": "இவை எப்படி இணைந்து செயல்படுகின்றன",
  "fit.combined.lead": "நீங்கள் ஒன்றுக்கு மேற்பட்ட தொழில் வகை அல்லது செயல்பாட்டைத் தேர்ந்தெடுத்துள்ளீர்கள். {site} உங்களை ஒரே வகைக்குள் அடைக்காது: கீழே உள்ள பகுதிகள் ஒரே மையத்தில் அருகருகே இயங்குகின்றன.",
  "fit.combined.activities": "ஒவ்வொரு செயல்பாடும் தன் சொந்தக் கட்டணங்களையும் விதிகளையும் வைத்திருக்கும். ஒரு கோர்ட் பல செயல்பாடுகளை வழங்கலாம்; ஒரு நேரத்தில் ஒரு முன்பதிவு, ஒவ்வொரு முன்பதிவும் எந்தச் செயல்பாட்டுக்கானது என்று பதியும்.",
  "fit.combined.rules": "முன்பதிவு விதிகளை முழு மையத்துக்கும், ஒரு செயல்பாட்டுக்கும் அல்லது ஒரு கோர்ட்டுக்கும் அமைக்கலாம்; மிகவும் குறிப்பிட்டது பொருந்தும்.",
  "fit.combined.models": "முழுவதுமாக முன்பதிவாகும் கோர்ட்டுகள், இடங்களுடன் பகிரப்படும் வசதிகள், வகுப்புகள், உபகரண வாடகை ஆகியவை அருகருகே இருக்கும்; ஒவ்வொன்றும் அதன் உண்மையான முறையில் முன்பதிவாகும்.",
  "fit.combined.staff": "அதே ஊழியர்கள் ஒருமுறை உள்நுழைவார்கள். மேலாளர்கள் அமைப்பார்கள்; முகப்பு மேசை நாள் பட்டியலையும் கவுண்டரையும் கவனிக்கும்.",
  "fit.combined.branches": "பல இடங்கள் ஒரே தொழிலின் கிளைகள்; அவை அனைத்துக்கும் ஒரே உள்நுழைவு.",
  "fit.from": "{list} இலிருந்து",
  "fit.sec.cta": "தொடங்கத் தயாரா?",
