  "pso.scope.booking": "முழு முன்பதிவுக்கும் செலுத்தும்",
  "pso.scope.resource": "முழுமையாக வாடகைக்கு எடுக்கப்பட்ட வசதிக்குச் செலுத்தும்",
  "pso.scope.participant": "ஒருவரின் இடத்துக்குச் செலுத்தும்",
  "pso.scope.places": "முன்பதிவில் உள்ள ஒவ்வொரு இடத்துக்கும் செலுத்தும்",
  "pso.buy": "வாங்கு · {cur}{price}",
  "pso.price": "{cur}{price}",
  "pso.whoFor": "யாருடைய இடத்துக்கு இது செலுத்தும்?",
  "pso.me": "என்னுடையது",
  "pso.cancel": "ரத்துசெய்",
  "pso.rules": "நீங்கள் மையத்தின் சொந்தக் கட்டணப் பக்கத்தில் செலுத்துகிறீர்கள்; செலுத்தியதும் பாஸ் உங்களுடையது. அது உங்கள் கணக்கின் தொலைபேசி எண்ணில் வைக்கப்பட்டு, அந்த எண்ணில் நீங்கள் செய்யும் முன்பதிவுகளுக்குப் பயன்படுத்தப்படும்; ஒருவரின் இடத்துக்கான பாஸ் அவரது இடத்துக்கு மட்டுமே செலுத்தும். பயன்படுத்தாத பகுதியைத் திருப்பித் தருவது பற்றி மையமே முடிவு செய்யும்.",
  "pso.signIn": "பாஸை ஆன்லைனில் வாங்க உள்நுழையுங்கள்",
  "pso.noPhone": "பாஸ் வாங்க உங்கள் கணக்கில் தொலைபேசி எண்ணைச் சேருங்கள்: பாஸ் அதில் வைக்கப்படும்",
  "pso.paidTitle": "உங்கள் பாஸ் தயார்",
  "pso.paidBody": "{venue} இல் {name} ({code}), {until} வரை செல்லும்.",
  "pso.paidFor": "இது {name} இன் இடத்துக்குச் செலுத்தும்.",
  "pso.notMadeTitle": "பாஸை வழங்க முடியவில்லை",
  "pso.notMadeBody": "உங்கள் கட்டணம் வந்துவிட்டது, ஆனால் அதற்குப் பாஸ் வழங்க முடியவில்லை. மையம் உங்களுக்கு {cur}{amount} திருப்பித் தர வேண்டும்.",
  "pso.notPaidBody": "எதுவும் வசூலிக்கப்படவில்லை, பாஸும் வழங்கப்படவில்லை.",
  "pso.back": "மையத்துக்குத் திரும்பு",
  "pso.err.PSO_REQUEST": "வாங்க ஒரு பாஸைத் தேர்ந்தெடுங்கள்.",
  "pso.err.PSO_NOT_SOLD": "அந்தப் பாஸ் இங்கே ஆன்லைனில் விற்கப்படுவதில்லை.",
  "pso.err.PSO_NOT_FOR_PARTICIPANT": "இந்தப் பாஸ் உங்கள் சொந்த முன்பதிவுகளுக்குச் செலுத்தும்: வேறொருவருக்காக வாங்க முடியாது.",
  "pso.err.PSO_NO_PHONE": "முதலில் உங்கள் கணக்கில் தொலைபேசி எண்ணைச் சேருங்கள்: உங்கள் பாஸ் அதில் வைக்கப்படும்.",
  "pso.err.PSO_PAUSED": "{name} உடனான உங்கள் உறவு மறுஆய்வுக்காக இடைநிறுத்தப்பட்டுள்ளது, எனவே இப்போது அவருக்குப் பாஸ் வாங்க முடியாது.",
  "pso.err.PSO_NOT_GUARDIAN": "நீங்கள் கவனித்துக்கொள்ளும் ஒருவருக்கு மட்டுமே பாஸ் வாங்க முடியும்.",
  "pso.err.PSO_OFFLINE": "இந்த மையம் தற்போது பாஸ்களை ஆன்லைனில் விற்பதில்லை. கவுண்டரில் வாங்குங்கள்.",
  "gcap.passes-online.title": "ஆன்லைனில் விற்கப்படும் பாஸ்கள்",
  "gcap.passes-online.blurb": "நீங்கள் தேர்ந்தெடுக்கும் பாஸ்களை வாடிக்கையாளர்கள் உங்கள் சொந்தப் பக்கத்திலிருந்து வாங்கி, உங்கள் கட்டணக் கணக்கு வழியாகச் செலுத்துகிறார்கள்; கட்டணம் வந்த பிறகே பாஸ் வழங்கப்படும்.",
  "fit.s.pass-sell.x.online": "மேலாளர் ஒரு பாஸை ஆன்லைனிலும் வழங்கலாம்: வாடிக்கையாளர் அதை மையத்தின் பக்கத்தில் வாங்கி, மையத்தின் கட்டணக் கணக்கு வழியாகச் செலுத்துகிறார்; செலுத்தியதும் பாஸ் வழங்கப்படும்.",
