  "bowl.perPlayerGame": "ஒருவருக்கு, ஒரு ஆட்டத்துக்கு",
  "err.GAMES_NEEDED": "இங்கு {sport} ஆட்ட அடிப்படையில் முன்பதிவு செய்யப்படுகிறது: எத்தனை ஆட்டங்கள் என்று சொல்லுங்கள், 1 முதல் {max} வரை.",
  "err.GAMES_NOT_HERE": "இது நேர அடிப்படையில் முன்பதிவு செய்யப்படுகிறது, ஆட்ட அடிப்படையில் அல்ல.",
  "err.GAMES_RANGE": "எத்தனை ஆட்டங்கள் என்று சொல்லுங்கள்: 1 முதல் {max} வரை.",
  "err.GAMES_ADD_SETTLED": "இன்னும் எதுவும் செலுத்தப்படாத முன்பதிவில் மட்டுமே ஆட்டங்களைச் சேர்க்க முடியும். கூடுதல் ஆட்டங்களை அதே தடத்தில் தனி முன்பதிவாகச் செய்யுங்கள்.",
  "err.GAMES_ADD_TAKEN": "இதற்குப் பிறகு {court} முன்பதிவு செய்யப்பட்டுள்ளது: மேலும் ஆட்டங்களுக்குத் தடம் காலியாக இல்லை.",
  "err.GAMES_NO_WAITLIST": "ஆட்ட அடிப்படையிலான முன்பதிவுக்குக் காத்திருப்புப் பட்டியல் இல்லை. வேறு நேரத்தைத் தேர்ந்தெடுங்கள்.",
  // nbk (entry with no set time, lib/entries.ts)
