  "tm.ui.linkText": "{site} இல் {team} இல் சேருங்கள்: {link}",
  "tm.ui.openInvites": "அனுப்பிய அழைப்புகள்",
  "tm.ui.byEmail": "மின்னஞ்சல் மூலம்",
  "tm.ui.byLink": "இணைப்பு மூலம்",
