  "tm.ui.withdraw": "திரும்பப் பெறு",
  "tm.ui.addChild": "நீங்கள் கவனித்துக்கொள்ளும் குழந்தையை அணியில் சேர்",
  "tm.ui.addChildNote": "பாதுகாவலராக நீங்கள் அவர்களுக்காகச் சம்மதிக்கிறீர்கள். அவர்களின் பெயர் உங்களுக்கும் தலைவருக்கும் மட்டுமே காட்டப்படும், பொதுவில் ஒருபோதும் இல்லை.",
  "tm.ui.choosePerson": "யார்",
  "tm.ui.addChildButton": "அணியில் சேர்",
  "tm.ui.dob": "பிறந்த தேதி",
  "tm.ui.dobNote": "ஒரு நிகழ்வின் வயது வரம்பைச் சரிபார்க்க மட்டுமே: இது உங்கள் சொல், சரிபார்க்கப்படாது, யாருக்கும் காட்டப்படாது.",
  "tm.ui.dobSaid": "ஒரு தேதி சேமிக்கப்பட்டுள்ளது.",
