  "tm.ui.description": "அணியைப் பற்றி",
  "tm.ui.history": "வரலாறு",
  "tm.ui.historyNone": "இன்னும் எதுவும் பதிவு செய்யப்படவில்லை.",
  "tm.ui.won": "வெற்றி",
  "tm.ui.lost": "தோல்வி",
  "tm.ui.drew": "சமன்",
  "tm.ui.against": "{team} க்கு எதிராக",
  "tm.ui.enterTeam": "நீங்கள் தலைவராக உள்ள அணியைப் பதிவு செய்யுங்கள்",
  "tm.ui.pickRoster": "யார் விளையாடுகிறார்கள் (அணியின் உறுப்பினர்களிலிருந்து)",
  "tm.ui.pickNote": "ஒவ்வொருவரும் அணியில் அவர்கள் அறிவித்தவற்றின்படி (வயது, பெண் அல்லது ஆண், உறுப்பினர் தகுதி) இந்த நிகழ்வின் விதிகளுடன் சரிபார்க்கப்படுகிறார்கள். எதுவும் உறுதிசெய்யப்படுவதில்லை.",
  "tm.ui.openTeam": "அணியைத் திற",
  "tm.ui.typedInstead": "அல்லது முன்பு போல கீழே அணியையும் அதன் பட்டியலையும் தட்டச்சு செய்யுங்கள்.",
  "tm.inv.title": "அணியில் சேருங்கள்",
  "tm.inv.noToken": "இந்தப் பக்கத்திற்குத் தலைவர் உங்களுக்கு அனுப்பிய இணைப்பு தேவை.",
  "tm.inv.intro": "{by} உங்களை {team} ({sport}) அணியில் சேர அழைத்தார். சேர்ந்தால், அணி பதிவு செய்யும் நிகழ்வுகளுக்குத் தலைவர் உங்களைத் தேர்ந்தெடுக்கலாம்; எப்போது வேண்டுமானாலும் விலகலாம்.",
  "tm.inv.forChild": "உங்களுக்குப் பதிலாக நீங்கள் கவனித்துக்கொள்பவரை அணியில் சேருங்கள்",
  "tm.inv.me": "நான்",
  "tm.inv.childNote": "பாதுகாவலராக அவர்களுக்காக நீங்கள் சம்மதிக்கிறீர்கள்; அவர்களின் பெயர் உங்களுக்கும் தலைவருக்கும் மட்டும் காட்டப்படும்.",
  "tm.inv.accept": "அணியில் சேர்",
  "tm.inv.joined": "நீங்கள் {team} இல் உள்ளீர்கள்.",
  "tm.inv.open": "அணியைத் திற",
  "tm.inv.signIn": "இந்த அழைப்பிற்குரிய கணக்கில் உள்நுழைந்து, மீண்டும் இங்கு வாருங்கள்.",
  "tml.title": "அணி லீக்குகள்",
  "tml.intro": "அணிகள் ஒரு பருவம் முழுவதும் போட்டி இரவுகளில், இடத்தின் ஆடுகளங்களில், சொந்த மற்றும் வெளி ஆட்டங்களாக விளையாடுகின்றன; அட்டவணை அவர்களின் நிலையைக் காட்டுகிறது.",
  "tml.none": "இப்போது அணி லீக்குகள் இல்லை.",
  "tml.legs.1": "ஒவ்வொரு அணியும் மற்ற ஒவ்வொரு அணியையும் ஒருமுறை சந்திக்கும்",
  "tml.legs.2": "சொந்த மற்றும் வெளி ஆட்டங்கள்",
