  "err.RT_NOT_FOUND": "அந்தப் போட்டி, முடிவு அல்லது மதிப்பீடு இல்லை.",
  "err.RT_STARTED": "போட்டி தொடங்கும் முன்பே அதன் மதிப்பீடுகள் தேர்ந்தெடுக்கப்படும்; இது ஏற்கனவே தொடங்கிவிட்டது.",
  "err.RT_REASON": "காரணத்தைக் கொடுங்கள், சில சொற்கள் (3 முதல் 200 எழுத்துகள்).",
  "err.RT_NOT_A_RESULT": "அந்த முடிவு இந்த மையத்தின் மதிப்பீடுகளில் இல்லை.",
  "err.RT_ALREADY_EXCLUDED": "அந்த முடிவு ஏற்கனவே விலக்கப்பட்டுள்ளது.",
  "err.RT_NOT_EXCLUDED": "அந்த முடிவு விலக்கப்படவில்லை.",
  "err.RT_NO_SUBJECT": "இங்கே அவர்களுக்கு இன்னும் எதுவும் மதிப்பிடப்படவில்லை.",
  "err.RT_SEED_DRAWN": "சீட்கள் குலுக்கலுக்கு முன்பே அமைக்கப்படும்: இந்தப் போட்டி ஏற்கனவே குலுக்கப்பட்டது அல்லது முடிந்தது.",
  "err.RT_SEED_CHANGED": "நீங்கள் பார்த்ததிலிருந்து மதிப்பீடுகள் மாறிவிட்டன. சீட்களை மீண்டும் பரிந்துரைக்கவும்.",
  "err.RT_SEED_EXISTS": "இந்தப் போட்டிக்கு சீட்கள் ஏற்கனவே அமைக்கப்பட்டுள்ளன: மதிப்பீடுகள் அவற்றை ஒருபோதும் மாற்றாது.",
  "err.RT_BASIS": "தெரிவித்த நிலை, பெற்ற நிலை அல்லது இரண்டில் எதுவும் என்பதைத் தேர்ந்தெடுக்கவும்.",
  "err.RT_NAME_NEEDED": "தரவரிசையில் காட்ட வேண்டிய பெயரைக் கொடுங்கள்.",
  "err.RT_ADULTS_ONLY": "தாங்கள் 18 அல்லது அதற்கு மேற்பட்டவர்கள் என்று கூறும் வீரர்கள் மட்டுமே தங்கள் மதிப்பீட்டை மற்றவர்களுக்குக் காட்டவோ தரவரிசையில் பட்டியலிடப்படவோ முடியும்.",
  "rt.title": "உங்கள் மதிப்பீடுகள்",
  "rt.intro": "ஒரு மையம் மதிப்பீடு செய்யப்படுவதாகக் குறித்த போட்டிகளின் முடிவுகளிலிருந்து மதிப்பீடு கணக்கிடப்படுகிறது. அது {start} இல் தொடங்கி, ஒவ்வொரு முடிவும் வெளியிடப்பட்ட ஒரே விதிப்படி அதை மாற்றுகிறது: எதுவும் கற்றுக்கொள்ளப்படுவதில்லை, உங்களிடமிருந்து எதுவும் மறைக்கப்படுவதில்லை. நீங்கள் காட்ட விரும்பினாலன்றி நீங்கள் (மற்றும் குழந்தையின் பாதுகாவலர்) மட்டுமே அதைப் பார்க்கலாம். {n} கணக்கிடப்பட்ட முடிவுகள் வரும்வரை அது தற்காலிகமானது.",
  "rt.none": "மதிப்பீடு செய்யப்பட்ட முடிவுகள் இன்னும் இல்லை. மையம் மதிப்பீட்டுக்காகக் குறித்த போட்டியில் நீங்கள் விளையாடும்போது, உங்கள் மதிப்பீடு இங்கே தோன்றும்.",
  "rt.signIn": "உங்கள் மதிப்பீடுகளைப் பார்க்க உள்நுழையுங்கள்.",
  "rt.preferences": "பொருத்தத்திற்கு எந்த நிலையைப் பயன்படுத்துவது, மற்றவர்கள் எதைப் பார்ப்பது என்பதைத் தேர்ந்தெடுக்கவும்",
