  "swiss.ui.points": "புள்",
  "swiss.ui.buchholz": "புக்.",
  "swiss.ui.byes": "{n} பை",
  "swiss.ui.next": "முந்தைய சுற்றின் அனைத்து ஆட்டங்களும் முடிந்தவுடன் சுற்று {n} இணைக்கப்படும்.",
  "swiss.ui.round": "சுற்று {n}",
  "swiss.ui.done": "அனைத்தும் முடிந்தன",
