  "tour.swiss": "ஸ்விஸ் சுற்றுகள்",
  "ldp.title": "கிளப் ஏணிகள்",
  "ldp.intro": "ஏணி தனது வீரர்களுக்குத் தரவரிசை தருகிறது. உங்களுக்கு சில இடங்கள் மேலுள்ளவரைச் சவால் செய்யுங்கள், ஆட்டத்தை ஏற்பாடு செய்து மதிப்பெண்ணைத் தெரிவியுங்கள்: வென்றால் அவர் இடத்தைப் பிடிப்பீர்கள்.",
  "ldp.none": "தற்போது திறந்த ஏணிகள் இல்லை.",
  "ldp.back": "எல்லா ஏணிகளும்",
  "ldp.how": "உங்களுக்கு மேல் {reach} இடங்கள் வரை உள்ள வீரரைச் சவால் செய்யலாம். அவர் பதிலளிக்க {respond} நாட்கள் உண்டு, இல்லையெனில் ஆட்டம் தோல்வியாகி நீங்கள் அவர் இடத்தைப் பிடிப்பீர்கள். ஏற்றபின் {play} நாட்களுக்குள் விளையாடுங்கள். கீழிருந்து சவால் செய்து வென்றவர் உயர்ந்த இடத்தைப் பெறுவார்; இடையிலுள்ளவர்கள் ஓர் இடம் கீழே இறங்குவர்.",
  "ldp.audience.adults": "பெரியவர்களுக்கு",
  "ldp.audience.juniors": "சிறுவர்களுக்கு",
  "ldp.juniorNote": "சிறுவர் ஏணியில் பெற்றோர் அல்லது பாதுகாவலர் குழந்தைக்காகச் சேர்ந்து அவர்கள் சார்பில் பதிலளிப்பார். பெயர்கள் முதல் பெயரும் முதலெழுத்தும் மட்டும் காட்டப்படும்; யாருடைய தொடர்பு விவரங்களும் காட்டப்படாது.",
  "ldp.players": "{n} வீரர்கள்",
  "ldp.season": "பருவம் {n}",
  "ldp.archive": "முந்தைய பருவங்கள்",
  "ldp.finalOrder": "இறுதி வரிசை",
  "ldp.ranks": "ஏணி",
