  "pmsg.back": "அனைத்துச் செய்திகள்",
  "pmsg.write": "செய்தி எழுதுக",
  "pmsg.send": "அனுப்பு",
  "pmsg.sending": "அனுப்புகிறது…",
  "pmsg.counter": "{n} / {max}",
  "pmsg.empty": "இன்னும் செய்திகள் இல்லை. வணக்கம் சொல்லுங்கள்.",
  "pmsg.reminder": "உரை மட்டும். தொலைபேசி எண்களையும் மின்னஞ்சல் முகவரிகளையும் அனுப்ப முடியாது. இணைப்புகள் வெறும் உரையாகக் காட்டப்படும்: நம்பாத இணைப்பைத் திறக்காதீர்கள்.",
  "pmsg.newMessages_one": "{n} புதிய செய்தி",
  "pmsg.newMessages_other": "{n} புதிய செய்திகள்",
  "pmsg.removed": "செய்தி நீக்கப்பட்டது",
  "pmsg.mute": "இந்த உரையாடலை ஒலியடக்கு",
  "pmsg.unmute": "ஒலியடக்கத்தை நீக்கு",
  "pmsg.muteNote": "ஒலியடக்கப்பட்டது: மின்னஞ்சல் இல்லை, எண்ணிக்கை இல்லை. நீங்கள் இன்னும் படிக்கவும் எழுதவும் முடியும்.",
  "pmsg.phase.read_only": "இந்த உரையாடல் முடிந்துவிட்டது. இன்னும் சிறிது காலம் படிக்கலாம், எழுத முடியாது.",
  "pmsg.phase.paused": "மையத்தின் ஊழியர்கள் இந்த உரையாடலை இடைநிறுத்தியுள்ளனர்.",
  "pmsg.block": "தடு",
  "pmsg.blocked": "தடுக்கப்பட்டது. அவர்கள் எழுதுவது உங்களை அடையாது, நீங்கள் எழுதுவது அவர்களை அடையாது.",
  "pmsg.report": "புகார்",
