  "clsb.c.rollCall": "வருகை எடு",
  "err.LAUNCH_WINDOW": "அந்த நேரம் படகு இறக்கும் நேரத்துக்கு ({window}) வெளியே உள்ளது. அதற்குள் ஒரு நேரத்தைத் தேர்ந்தெடுங்கள்.",
  "err.LAUNCH_RETURN": "வாடகைப் பொருளை {back}க்குள் திருப்பித் தர வேண்டும் — இறக்கும் நேரம் முடிவதற்கு {minutes} நிமிடங்கள் முன்பு. முன்னதாக முடியும் நேரத்தைத் தேர்ந்தெடுங்கள்.",
  "err.LAUNCH_CLOSED": "அன்று படகு இறக்கும் நேரம் இல்லை, எனவே முன்பதிவு செய்ய முடியாது.",
  "err.TIDE_NO_DATA": "அந்த நாளுக்கான அலை நேரங்களை மையம் இன்னும் உள்ளிடவில்லை, எனவே இப்போது முன்பதிவு செய்ய முடியாது. வேறு நாளை முயலுங்கள் அல்லது மையத்திடம் கேளுங்கள்.",
  "err.LAUNCH_WEEK": "{date} அன்று முன்பதிவு இறக்கும் நேரத்துக்கு வெளியே விழும். வேறு நாளைத் தேர்ந்தெடுங்கள் அல்லது வாரங்களைக் குறையுங்கள்.",
  "wtr1.reason.outside_launch": "இறக்கும் நேரத்துக்கு வெளியே",
