  "lad2.ui.forfeit": "அரங்கிடம் வெளியேற்றம் கோரவும்",
  "lad2.ui.forfeitWho": "வெளியேற்றம் கோரப்படும் அணி",
  "lad2.ui.forfeitNote": "குறிப்பு (மற்ற காரணத்திற்குத் தேவை)",
  "lad2.ui.forfeitSend": "கோரு",
  "lad2.ui.forfeitOpen": "{team} வெளியேறவேண்டும் என்று {by} கோரினார். அரங்கின் மேலாளர் மட்டுமே வழங்க முடியும்.",
  "lad2.ui.forfeitWithdraw": "கோரிக்கையைத் திரும்பப் பெறு",
  // Swiss: accelerated pairing, the tie-break screen and Swiss for counted performance events (ADR 0038; lib/swiss.ts, lib/swiss-performances.ts)
  "swiss.ui.tb.buchholz_cut1": "குறைந்த எதிராளி இல்லாத புக்கோல்ஸ்",
  "swiss.ui.tb.sonneborn_berger": "சொன்னபோர்ன்-பெர்கர் (வென்ற எதிராளிகளின் புள்ளிகள், சமனுக்குப் பாதி)",
  "swiss.ui.tbs.buchholz": "புக்.",
  "swiss.ui.tbs.median_buchholz": "நடு.",
  "swiss.ui.tbs.buchholz_cut1": "கட்-1",
  "swiss.ui.tbs.sonneborn_berger": "சொ-பெ",
  "swiss.ui.tbs.wins": "வெற்றி",
  "swiss.ui.tbs.set_diff": "செட் +/-",
  "swiss.ui.tbs.set_ratio": "செட் வி.",
  "swiss.ui.tbs.point_diff": "புள்ளி +/-",
  "swiss.ui.tbs.point_ratio": "புள்ளி வி.",
  "swiss.ui.tbs.points_for": "பெற்றவை",
  "swiss.ui.tbs.head_to_head": "நேர்",
  "swiss.ui.accel": "வேகப்படுத்தப்பட்ட இணைப்பு: சுற்று 1 முதல் {rounds} வரை, தொடக்க வரிசையின் சிறந்த {group} பேர் ஒரு புள்ளி கூடுதல் இருப்பது போல இணைக்கப்பட்டனர், இதனால் வலிமையானவர்கள் முன்பே சந்திக்கிறார்கள். அந்தப் புள்ளி முடிவு அல்ல, எந்த அட்டவணையிலும் இல்லை.",
  "swiss.ui.accelShort": "வேகப்படுத்தப்பட்டது",
  "swpf.mail.s": "{t} போட்டியின் சுற்று {round}",
  "swpf.mail.group": "{t} சுற்று {round}: நீங்கள் {heat}-ஆம் குழுவில், {lane}-ஆவதாகத் தொடங்குகிறீர்கள்: {date} {time}, {court}.",
  "swpf.mail.unplaced": "{t} சுற்று {round}: நீங்கள் {heat}-ஆம் குழுவில், {lane}-ஆவதாகத் தொடங்குகிறீர்கள். ஆடுகளம் கிடைத்ததும் நேரம் போட்டியின் பக்கத்தில் இருக்கும்.",
  "swpf.ui.title": "{total} சுற்றுகளில் {played} முடிந்த பின் நிலவரம்",
  "swpf.ui.rule.sum": "ஒவ்வொரு சுற்றிலும் அனைத்துக் குழுக்களிலும் பெற்ற இடம் கூட்டப்படுகிறது: குறைந்த புள்ளி வெல்லும். ஒரு சுற்றில் முடிவு இல்லாத ஏறுபவர், முடிவு உள்ள கடைசி நபருக்கு ஒரு இடம் பின்னால் வைக்கப்படுவார். சமமாக இருந்தால்: சிறந்த சுற்று இடங்கள், பின்னர் குலுக்கல்.",
